/**
 * The server's leg of the v2 vectors (spec D15) — real Rust crypto via bun:ffi.
 *
 * MUST run under `bun test`, NOT vitest (vitest aliases `@llamenos/crypto/ffi`
 * to a pure-TS stand-in whose bytes are not the wire format):
 *   bun test apps/worker/__tests__/integration-bun/v2-vectors.test.ts
 *
 * `packages/crypto/tests/fixtures/v2/` is generated by the crate from a seeded
 * RNG (`packages/crypto/src/vectors.rs`). This opens every positive vector
 * through the server's production binding and asserts each negative vector's
 * closed rejection code — never merely that something failed:
 *  - hpke-wrap.json (D1, D2): one `{enc, ct}` per shape; wrong shape, base64url,
 *    uppercase and wrong lengths are refused with their codes.
 *  - server-event.json (D9, #2999): the keys the server hands a member of hub A
 *    are exactly the ones it derives, the frames the relay seals for hub A open
 *    with them, and a frame moved between hubs, kinds or epochs does not.
 */
import { describe, expect, it } from 'bun:test'
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import {
  CryptoError,
  SHAPES,
  openServerEvent,
  sealServerEvent,
  serverEventKey,
  shapeOpen,
  type HpkeEnvelope,
  type Shape,
} from '@llamenos/crypto/ffi'
import { bytesToHex, hexToBytes } from '@shared/encoding'

const FIXTURES = resolve(import.meta.dir, '../../../../packages/crypto/tests/fixtures/v2')
const load = (name: string) => JSON.parse(readFileSync(resolve(FIXTURES, name), 'utf-8'))

function reasonOf(fn: () => unknown): string | null {
  try {
    fn()
  } catch (err) {
    if (err instanceof CryptoError) return err.reason
    throw err
  }
  throw new Error('expected a rejection, got success')
}

describe('v2 hpke-wrap vectors through the server binding', () => {
  const f = load('hpke-wrap.json') as {
    recipientSecretHex: string
    positives: { shape: Shape; aadFields: string[]; plaintextHex: string; envelope: HpkeEnvelope }[]
    negatives: { name: string; shape: Shape; aadFields: string[]; envelope: HpkeEnvelope; expect: string }[]
  }
  const secret = hexToBytes(f.recipientSecretHex)

  it('lists every shape, in the C-ABI byte order ffi.ts uses', () => {
    expect(f.positives.map(p => p.shape)).toEqual([...SHAPES])
  })

  for (const p of f.positives) {
    it(`opens ${p.shape}`, () => {
      expect(bytesToHex(shapeOpen(p.shape, secret, p.aadFields, p.envelope))).toBe(p.plaintextHex)
    })
  }

  for (const n of f.negatives) {
    it(`refuses ${n.name} with ${n.expect}`, () => {
      expect(reasonOf(() => shapeOpen(n.shape, secret, n.aadFields, n.envelope))).toBe(n.expect)
    })
  }
})

describe('v2 server-event vectors through the server binding', () => {
  const f = load('server-event.json') as {
    serverSecretHex: string
    heldKeys: { hubId: string; epoch: number; keyHex: string }[]
    frames: { name: string; hubId: string; kind: number; epoch: number; plaintext: string; payload: string }[]
    negatives: { name: string; hubId: string; kind: number; epoch: number; payload: string; expect: string }[]
  }
  const secret = hexToBytes(f.serverSecretHex)
  const held = (hub: string, epoch: number) => f.heldKeys.find(k => k.hubId === hub && k.epoch === epoch)

  it('derives exactly the keys a member of hub A is handed', () => {
    for (const k of f.heldKeys) expect(bytesToHex(serverEventKey(secret, k.hubId, k.epoch))).toBe(k.keyHex)
  })

  for (const fr of f.frames) {
    it(`${fr.name}: opens with its hub's key, and only that hub's member holds it`, () => {
      const own = serverEventKey(secret, fr.hubId, fr.epoch)
      expect(openServerEvent(own, fr.hubId, fr.kind, fr.epoch, fr.payload)).toBe(fr.plaintext)
      expect(Boolean(held(fr.hubId, fr.epoch))).toBe(fr.hubId === f.heldKeys[0].hubId)
    })
  }

  it('what the relay seals opens, and only as its own hub, kind and epoch', () => {
    const fr = f.frames[0]
    const payload = sealServerEvent(secret, fr.hubId, fr.kind, fr.epoch, fr.plaintext)
    const key = serverEventKey(secret, fr.hubId, fr.epoch)
    expect(openServerEvent(key, fr.hubId, fr.kind, fr.epoch, payload)).toBe(fr.plaintext)
    expect(reasonOf(() => openServerEvent(key, fr.hubId, fr.kind + 1, fr.epoch, payload))).toBe('decryption_failed')
  })

  for (const n of f.negatives) {
    if (n.expect === 'no_event_key') continue // a keyring property: the server hands no key, see above
    it(`refuses ${n.name} with ${n.expect}`, () => {
      const k = held(f.heldKeys[0].hubId, n.epoch) ?? f.heldKeys[0]
      expect(reasonOf(() => openServerEvent(hexToBytes(k.keyHex), n.hubId, n.kind, n.epoch, n.payload))).toBe(n.expect)
    })
  }
})
